ui.css:
.ct-panel { background: #3a5055; border-radius: 12px; padding: 10px 14px; color: #fff; font: 400 26px 'Jersey 10', monospace; box-shadow: 0 4px 0 #26353a, -3px 9px 0 rgba(0,0,0,.32); }
.ct-well { background: #26353a; border-radius: 8px; padding: 2px 18px; font: 400 47px 'Jersey 10', monospace; text-shadow: -2px 3px 0 rgba(0,0,0,.4); }
.ct-bar { width: 210px; height: 24px; background: #26353a; border-radius: 8px; overflow: hidden; }
.ct-bar-fill { height: 100%; background: #fe5f55; border-radius: 8px; box-shadow: inset 0 -5px 0 #c2453e, inset 0 3px 0 rgba(255,255,255,.3); }
.ct-blue-fill { background: #009dff; box-shadow: inset 0 -5px 0 #0067b0, inset 0 3px 0 rgba(255,255,255,.3); }
.ct-title { font: 400 75px/1 'Jersey 10', monospace; color: #f3b958; text-shadow: -3px 5px 0 rgba(0,0,0,.45); animation: ctWobble 2.4s ease-in-out infinite; }
.ct-card { width: 220px; min-height: 296px; padding: 20px 14px 16px; background: #4f6367; border-radius: 14px; box-shadow: 0 5px 0 #374244, -4px 12px 0 rgba(0,0,0,.35); transition: transform .2s cubic-bezier(.3,1.7,.5,1); animation: ctDeal .55s cubic-bezier(.3,1.5,.5,1) backwards; }
.ct-card:hover { transform: translateY(-10px) rotate(-2deg) scale(1.05); }
.ct-desc { background: #fff; color: #374244; border-radius: 9px; padding: 9px 10px; font: 400 21px/1.1 'Jersey 10', monospace; box-shadow: inset 0 -4px 0 #bfc7d5; }
.ct-badge { width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; background: #fe5f55; color: #fff; box-shadow: 0 3px 0 #c2453e; font: 400 22px 'Jersey 10', monospace; }
.ct-button { background: #fda200; color: #fff; border-radius: 8px; padding: 4px 14px; box-shadow: 0 4px 0 #b97500; font: 400 23px 'Jersey 10', monospace; }
@keyframes ctWobble { 0%, 100% { transform: rotate(-1.6deg) scale(1); } 50% { transform: rotate(1.6deg) scale(1.04); } }
@keyframes ctDeal { from { transform: translateY(70px) rotate(9deg) scale(.6); opacity: 0; } }
